void handle_timer_callback(struct snd_timer_instance *timeri, int event,
                           struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (!timeri->filter[event])
        return;

    if (!snd_timer_read_available(timeri))
        return;

    struct snd_timer_read *tr = &timeri->tread;
    tr->event = event;
    tr->tstamp = *tstamp;
    tr->resolution = resolution;

    spin_lock(&timeri->queue_lock);
    list_add_tail(&tr->queue, &timeri->queue);
    spin_unlock(&timeri->queue_lock);

    wake_up(&timeri->wait_queue);
    wake_up_interruptible(&timeri->sleep_queue);
}

void handle_timer_callback(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution) {
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (timeri->filter & (1 << event)) {
        struct snd_timer_read *tr;

        if (timeri->qlock)
            spin_lock_irq(timeri->qlock);

        tr = kmem_cache_alloc(timeri->readq, GFP_ATOMIC);
        if (!tr) {
            if (timeri->qlock)
                spin_unlock_irq(timeri->qlock);
            return;
        }

        tr->event = event;
        tr->tstamp = *tstamp;
        tr->resolution = resolution;

        list_add_tail(&tr->list, &timeri->queue);
        if (timeri->qlock)
            spin_unlock_irq(timeri->qlock);

        wake_up(&timeri->wait_queue);
        kill_fasync(&timeri->fasync, SIGIO, POLL_IN);
    }
}

void handle_timer_callback(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution) {
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (tstamp)
        memcpy(&timeri->timestamp, tstamp, sizeof(*tstamp));

    if ((timeri->filter & (1 << event)) == 0)
        return;

    if (timeri->q)
        return;

    struct snd_timer_read *tm = kmalloc(sizeof(*tm), GFP_KERNEL);
    if (!tm)
        return;

    tm->event = event;
    tm->resolution = resolution;
    tm->timestamp = timeri->timestamp;

    spin_lock_irq(&timeri->qlock);
    list_add_tail(&tm->list, &timeri->queue);
    spin_unlock_irq(&timeri->qlock);

    wake_up(&timeri->wait);
    wake_up_interruptible(&timeri->sleep_wait);
}

void handle_timer_event(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution) {
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (!timeri->tread || (timeri->filter & (1 << event)) == 0)
        return;

    struct snd_timer_read *tmread;
    tmread = kmalloc(sizeof(*tmread), GFP_KERNEL);
    if (!tmread)
        return;

    tmread->event = event;
    tmread->timestamp = *tstamp;
    tmread->resolution = resolution;

    spin_lock_irq(&timeri->qlock);
    list_add_tail(&tmread->list, &timeri->qhead);
    spin_unlock_irq(&timeri->qlock);

    wake_up(&timeri->qwait);
}

void handle_timer_event(struct snd_timer_instance *timeri, int event,
                        struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (timeri->filter && !(timeri->filter & (1 << event)))
        return;

    if (!snd_pcm_read_available(timeri->queue->subscribers))
        return;

    struct snd_timer_read *tr = &timeri->read;
    tr->event = event;
    tr->tstamp = *tstamp;

    snd_pcm_lock(timeri->queue);
    snd_pcm_enqueue(timeri->queue, tr);
    snd_pcm_unlock(timeri->queue);

    wake_up(&timeri->queue->wait);
    wake_up_interruptible(&timeri->queue->sleep);
}
